    expCallTransform 1 lam (betaOneCallCut k) ≤ (1 - lam)⁻¹

theorem betaTwoExpCallTransform_le (k : ℕ) (hk : 3 ≤ k) {lam : ℝ}
    (hlam : lam < 1) :
